<?php
namespace App\Livewire\Storefront;
use App\Models\CartItem; use App\Services\RecommendationService; use Livewire\Attributes\Layout; use Livewire\Component;
#[Layout('layouts.store')]
class Cart extends Component { public function change(int $id,int $quantity){ $item=CartItem::where('user_id',auth()->id())->findOrFail($id); if($quantity<1){$item->delete();$message='Produk dihapus dari keranjang.';} else {$item->update(['quantity'=>$quantity]);$message='Jumlah produk diperbarui.';} $this->dispatch('cart-updated'); $this->dispatch('toast', type: 'success', message: $message); } public function remove(int $id){CartItem::where('user_id',auth()->id())->findOrFail($id)->delete();$this->dispatch('cart-updated');$this->dispatch('toast', type: 'success', message: 'Produk dihapus dari keranjang.');} public function add(int $id){$item=CartItem::firstOrNew(['user_id'=>auth()->id(),'product_id'=>$id]);$item->quantity=($item->exists?$item->quantity:0)+1;$item->save();$this->dispatch('cart-updated');$this->dispatch('toast', type: 'success', message: 'Rekomendasi ditambahkan ke keranjang.');} public function render(RecommendationService $recommendations){$items=CartItem::where('user_id',auth()->id())->with('product.category')->get();return view('livewire.storefront.cart',['items'=>$items,'recommendations'=>$recommendations->forProductIds($items->pluck('product_id')->all())]);} }
